using System.IO.Compression;using Accyourate.App.Platform.Audit;using Accyourate.App.Platform.Notifications;
namespace Accyourate.App.Platform.Backup;
public sealed class RestoreService
{
 private readonly BackupService _backup=new();private readonly AuditService _audit=new();private readonly NotificationService _notifications=new();
 public void Restore(string backupPath,string restoredBy="System"){if(!_backup.VerifyBackup(backupPath))throw new InvalidOperationException("Backup non valido o checksum non corrispondente.");var app=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"AccyourateEnterpriseX");var temp=Path.Combine(Path.GetTempPath(),$"AccyourateRestore_{Guid.NewGuid():N}");Directory.CreateDirectory(temp);Directory.CreateDirectory(app);try{ZipFile.ExtractToDirectory(backupPath,temp,true);Copy(Path.Combine(temp,"databases","accyourate-hr.db"),Path.Combine(app,"accyourate-hr.db"));Copy(Path.Combine(temp,"databases","accyourate-assets.db"),Path.Combine(app,"accyourate-assets.db"));Copy(Path.Combine(temp,"databases","accyourate-platform.db"),Path.Combine(app,"accyourate-platform.db"));Copy(Path.Combine(temp,"settings","settings.json"),Path.Combine(app,"settings.json"));_audit.Track(AuditAction.Updated,$"Ripristinato backup {Path.GetFileName(backupPath)}","Backup",backupPath,Path.GetFileName(backupPath),restoredBy,AuditSeverity.Warning,"BackupCenter");_notifications.Publish("Ripristino completato",$"Ripristinato backup {Path.GetFileName(backupPath)}. Riavvia l'applicazione.",NotificationCategory.System,NotificationPriority.Info,restoredBy,"restore-complete",backupPath);}finally{if(Directory.Exists(temp))Directory.Delete(temp,true);}}
 private static void Copy(string source,string dest){if(!File.Exists(source))return;Directory.CreateDirectory(Path.GetDirectoryName(dest)??".");File.Copy(source,dest,true);}
}
